/// <summary>
/// Data contract class as a response for service <c>METSalesOrderCancelService</c>
/// </summary>
[DataContractAttribute]
class METSalesOrderLineResponseContract extends METBaseResponseContract
{
}

Method.Source:
    /// <summary>
    /// Contruct a new Response contract
    /// </summary>
    /// <param name = "_result">Result of the cancellation</param>
    /// <param name = "_message">Message Result</param>
    /// <returns>new contract</returns>
    public static METSalesOrderLineResponseContract newFromParameters(METProcessingStatus _result, Description255 _message)
    {
        METSalesOrderLineResponseContract salesOrderLineResponse = new METSalesOrderLineResponseContract();

        salesOrderLineResponse.parmResult(enum2Symbol(enumNum(METProcessingStatus), enum2int(_result)));
        salesOrderLineResponse.parmMessage(_message);

        return salesOrderLineResponse;
    }
